export function serviceMetaDescription(locationSlug: string | undefined, serviceSlug: string | undefined): string | undefined {
  if (!serviceSlug) return undefined;
  const location = locationSlug || 'the-sea-to-sky';
  return SERVICE_META_DESCRIPTIONS[`/${location}/services/${serviceSlug}/`];
}
